/** Picks a Team from the teams resource */
function TeamIdPicker({
  id,
  value,
  onChange,
  allowEmpty
}: {
  id: string;
  value: string;
  onChange: (value: string) => void;
  allowEmpty: boolean;
}) {
  const options = useQuery({ queryKey: ["teams", "list", { page_size: 200 }], queryFn: () => client.teams.list({ page_size: 200 }) });
  return (
    <select id={id} className={selectClass} value={value} onChange={e => onChange(e.target.value)}>
      {allowEmpty ? <option value="">—</option> : null}
      {(options.data?.data ?? []).map(item => (
        <option key={text(item.id)} value={text(item.id)}>
          {text(item.name)}
        </option>
      ))}
    </select>
  );
}

type InvoicesSetter = <K extends keyof InvoicesValues>(key: K, value: InvoicesValues[K]) => void;

function renderInvoicesField(field: InvoicesField, values: InvoicesValues, set: InvoicesSetter) {
  switch (field) {
    case "team_id":
      return (
      <FormRow label="Team" htmlFor="team_id">
        <TeamIdPicker id="team_id" value={values.team_id} onChange={value => set("team_id", value)} allowEmpty={false} />
      </FormRow>
      );
    case "customer":
      return (
      <FormRow label="Customer" htmlFor="customer">
        <Input id="customer" type="text" maxLength={160} value={values.customer} onChange={e => set("customer", e.target.value)} required />
      </FormRow>
      );
    case "currency":
      return (
      <FormRow label="Currency" htmlFor="currency">
        <select id="currency" className={selectClass} value={values.currency} onChange={e => set("currency", e.target.value as InvoicesValues["currency"])}>
          <option value="USD">USD</option>
          <option value="EUR">EUR</option>
          <option value="JPY">JPY</option>
        </select>
      </FormRow>
      );
    case "total":
      return (
      <FormRow label="Total" htmlFor="total">
        <div className="flex items-center gap-2">
          <Input id="total" type="text" inputMode="decimal" pattern={"-?\\d{1,15}(\\.\\d{1,4})?"} placeholder="0.00" title="A decimal amount with at most four fraction digits" value={values.total} onChange={e => set("total", e.target.value.trim())} required />
          <span className="text-sm text-muted-foreground">{values.currency}</span>
        </div>
      </FormRow>
      );
    case "fee":
      return (
      <FormRow label="Fee" htmlFor="fee">
        <div className="flex items-center gap-2">
          <Input id="fee" type="text" inputMode="decimal" pattern={"-?\\d{1,15}(\\.\\d{1,4})?"} placeholder="0.00" title="A decimal amount with at most four fraction digits" value={values.fee} onChange={e => set("fee", e.target.value.trim())} />
          <span className="text-sm text-muted-foreground">USD</span>
        </div>
      </FormRow>
      );
  }
}

function InvoicesForm({
  fields,
  initial,
  submitLabel,
  pending,
  error,
  onSubmit,
  onCancel
}: {
  fields: readonly InvoicesField[];
  initial: InvoicesValues;
  submitLabel: string;
  pending: boolean;
  error: { message: string } | null;
  onSubmit: (values: InvoicesValues) => void;
  onCancel?: () => void;
}) {
  const [values, setValues] = useState<InvoicesValues>(initial);
  const [problem, setProblem] = useState<string | null>(null);
  const set: InvoicesSetter = (key, value) => setValues(current => ({ ...current, [key]: value }));
  const submit = (event: FormEvent) => {
    event.preventDefault();
    setProblem(null);
    try {
      onSubmit(values);
    } catch (err) {
      setProblem(err instanceof Error ? err.message : String(err));
    }
  };
  return (
    <form onSubmit={submit} className="grid max-w-xl gap-4">
      {fields.map(field => (
        <Fragment key={field}>{renderInvoicesField(field, values, set)}</Fragment>
      ))}
      <ErrorNote error={error ?? (problem ? { message: problem } : null)} />
      <div className="flex gap-2">
        <Button type="submit" disabled={pending}>
          {submitLabel}
        </Button>
        {onCancel ? (
          <Button type="button" variant="ghost" onClick={onCancel}>
            Cancel
          </Button>
        ) : null}
      </div>
    </form>
  );
}

