function InvoicesNewInner() {
  const navigate = useNavigate();
  const queryClient = useQueryClient();
  const createRow = useMutation({
    mutationFn: (input: Input<"create">) => client.invoices.create(input),
    onSuccess: async row => {
      await queryClient.invalidateQueries({ queryKey: KEY });
      await navigate({ to: "/invoices/$id", params: { id: text(row.id) } });
    }
  });
  return (
    <Pane title="New invoice" actions={<Link to="/invoices" className={buttonVariants({ variant: "ghost", size: "icon-sm" })} aria-label="Back">
            <ArrowLeft />
          </Link>}>
      <InvoicesForm
        fields={INVOICES_CREATE}
        initial={EMPTY_INVOICES}
        submitLabel="Create"
        pending={createRow.isPending}
        error={createRow.error}
        onSubmit={values => createRow.mutate(toInvoicesCreateInput(values))}
      />
    </Pane>
  );
}

function InvoicesDetailInner() {
  const { id: rawId } = useParams({ from: "/invoices/$id" });
  const id = idOf(rawId);
  const navigate = useNavigate();
  const queryClient = useQueryClient();
  const [editing, setEditing] = useState(false);
  useEffect(() => {
    setEditing(false);
  }, [id]);
  const query = useQuery({ queryKey: [...KEY, "get", id], queryFn: () => client.invoices.get({ id }) });
  const session = useQuery({ queryKey: ["auth", "session"], queryFn: () => client.auth.session() });
  const user = sessionUser(session.data);
  void user;
  const updateRow = useMutation({
    mutationFn: (input: Inputs["invoices"]["update"]) => client.invoices.update(input),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: KEY });
      setEditing(false);
    }
  });
  const removeRow = useMutation({
    mutationFn: (input: Inputs["invoices"]["delete"]) => client.invoices.delete(input),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: KEY });
      await navigate({ to: "/invoices" });
    }
  });

  if (query.isPending) return <PaneSkeleton />;
  if (query.error) return <ErrorNote error={query.error} className="m-6" />;
  const row: Detail = query.data;
  void row;
  return (
    <Pane
      title={text(row.number) || "Invoice " + text(row.id)}
      actions={
        <>
          <Link to="/invoices" className={buttonVariants({ variant: "ghost", size: "icon-sm" })} aria-label="Back">
            <ArrowLeft />
          </Link>
          {canUpdate(user, row) ? (
            <Button variant="outline" size="sm" onClick={() => setEditing(current => !current)}>
              {editing ? "Cancel" : "Edit"}
            </Button>
          ) : null}
          {canDelete(user, row) ? (
            <Button
              variant="destructive"
              size="sm"
              disabled={removeRow.isPending}
              onClick={() => {
                if (window.confirm("Delete this invoice?")) removeRow.mutate({ id });
              }}
            >
              Delete
            </Button>
          ) : null}
        </>
      }
    >


      {editing ? (
        <InvoicesForm
          fields={INVOICES_UPDATE}
          initial={invoicesFromRow(row)}
          submitLabel="Save"
          pending={updateRow.isPending}
          error={updateRow.error}
          onCancel={() => setEditing(false)}
          onSubmit={values => updateRow.mutate({ id, data: toInvoicesUpdateInput(values) })}
        />
      ) : (
        <dl className="grid gap-3">
        <FieldRow label="Id">{text(row.id) || "—"}</FieldRow>
        <FieldRow label="Team">{text(row.team_id) || "—"}</FieldRow>
        <FieldRow label="Number">{text(row.number) || "—"}</FieldRow>
        <FieldRow label="Customer">{text(row.customer) || "—"}</FieldRow>
        <FieldRow label="Currency">{row.currency == null ? "—" : <Badge variant="secondary">{text(row.currency)}</Badge>}</FieldRow>
        <FieldRow label="Total">{formatMoney(row.total, row.currency) || "—"}</FieldRow>
        <FieldRow label="Fee">{formatMoney(row.fee, "USD") || "—"}</FieldRow>
        <FieldRow label="Created At">{formatDateTime(row.created_at) || "—"}</FieldRow>
        </dl>
      )}
    </Pane>
  );
}

export const InvoicesLayout = guarded(InvoicesLayoutInner);
export const InvoicesIndex = guarded(InvoicesIndexInner);
export const InvoicesNew = guarded(InvoicesNewInner);
export const InvoicesDetail = guarded(InvoicesDetailInner);
